/*
 * A191136  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x+1 and 4x+1 are in a.
 * https://oeis.org/A191136
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1; if x∈a then 3x+1∈a and 4x+1∈a. Algorithm: breadth‑first
 *            generation using a min‑heap, storing values in a static cache to
 *            allow arbitrary order of calls
 * Range:     u8 n <= 12, u16 n <= 575, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>

/* ----- heap helpers ----- */
typedef struct {
    seq_t *data;
    size_t len;
    size_t cap;
} minheap_t;

static void heap_grow(minheap_t *h)
{
    size_t newcap = h->cap ? h->cap * 2 : 8;
    seq_t *tmp = (seq_t *)realloc(h->data, newcap * sizeof(seq_t));
    if (!tmp) abort();                  /* memory failure */
    h->data = tmp;
    h->cap = newcap;
}

static void heap_push(minheap_t *h, seq_t v)
{
    if (h->len == h->cap) heap_grow(h);
    size_t i = h->len++;
    h->data[i] = v;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (h->data[p] <= h->data[i]) break;
        seq_t t = h->data[p]; h->data[p] = h->data[i]; h->data[i] = t;
        i = p;
    }
}

static seq_t heap_pop(minheap_t *h)
{
    seq_t ret = h->data[0];
    h->len--;
    if (h->len) {
        h->data[0] = h->data[h->len];
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            size_t r = l + 1;
            size_t smallest = i;
            if (l < h->len && h->data[l] < h->data[smallest]) smallest = l;
            if (r < h->len && h->data[r] < h->data[smallest]) smallest = r;
            if (smallest == i) break;
            seq_t t = h->data[i]; h->data[i] = h->data[smallest]; h->data[smallest] = t;
            i = smallest;
        }
    }
    return ret;
}

/* ----- main function ----- */
seq_t a(idx_t n)
{
    if (n < 1) return 0;               /* undefined; guard */

    static seq_t *cache = NULL;        /* sorted sequence cache */
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static minheap_t heap = {NULL, 0, 0};

    /* initialisation */
    if (cache_len == 0 && heap.len == 0) {
        heap.cap = 8; heap.data = (seq_t *)malloc(heap.cap * sizeof(seq_t));
        if (!heap.data) abort();
        heap_push(&heap, (seq_t)1);
        cache_cap = 8; cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (!cache) abort();
    }

    /* expand cache until we have n terms */
    while (cache_len < n) {
        seq_t x = heap_pop(&heap);
        if (cache_len == cache_cap) {
            size_t newcap = cache_cap ? cache_cap * 2 : 8;
            seq_t *tmp = (seq_t *)realloc(cache, newcap * sizeof(seq_t));
            if (!tmp) abort();
            cache = tmp;
            cache_cap = newcap;
        }
        cache[cache_len++] = x;

        seq_t c1 = 3 * x + 1;
        seq_t c2 = 4 * x + 1;
        heap_push(&heap, c1);
        heap_push(&heap, c2);
    }

    return cache[n - 1];
}
